html:
{%- set proposal = doc -%}
{%- set project = frappe.get_doc("Project", proposal.project) -%}
{%- set agency = frappe.get_doc("AgencyProfile", proposal.agency) -%}
{%- set client = frappe.get_doc("ClientProfile", project.client) if project.client else None -%}
{%- set generated_at = frappe.utils.now_datetime().strftime("%d/%m/%Y à %H:%M") -%}
{%- set submitted_display = frappe.utils.get_datetime(proposal.submitted_date).strftime("%d/%m/%Y à %H:%M") if proposal.submitted_date else generated_at -%}
{%- set deadline_display = frappe.utils.get_datetime(proposal.response_deadline).strftime("%d/%m/%Y à %H:%M") if proposal.response_deadline else None -%}
{%- set extended_display = frappe.utils.get_datetime(proposal.extended_deadline).strftime("%d/%m/%Y à %H:%M") if proposal.extended_deadline else None -%}
{%- set items = proposal.quote_items or [] -%}
{%- set vat_rate = proposal.vat_rate or 0 -%}
{%- set ns = namespace(subtotal=0) -%}
{%- for item in items -%}
	{%- set ns.subtotal = ns.subtotal + (item.quantity or 1) * (item.unit_price or 0) -%}
{%- endfor -%}
{%- if not items -%}
	{%- set ns.subtotal = proposal.amount or 0 -%}
{%- endif -%}
{%- set vat_amount = ns.subtotal * (vat_rate / 100) if vat_rate else 0 -%}
{%- set total = ns.subtotal + vat_amount -%}
{%- macro money(value) -%}{{ "{:,.0f}".format(value or 0).replace(",", " ") }} €{%- endmacro -%}
<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<title>Devis — {{ proposal.name }}</title>
<style>
	body { font-family: Arial, Helvetica, sans-serif; color: #1a1a1a; font-size: 12px; margin: 0; padding: 26px; background: #faf6f1; }
	.sheet { max-width: 680px; margin: 0 auto; background: #faf6f1; }

	.top-row { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 28px; page-break-inside: avoid; }
	.doc-title { font-size: 30px; font-weight: bold; letter-spacing: 0.02em; }
	.doc-ref { font-size: 12px; color: #555555; margin-top: 2px; }
	.meta-box { text-align: right; font-size: 11px; }
	.meta-line { margin-bottom: 4px; }
	.meta-label { font-weight: bold; }

	.parties-row { display: flex; justify-content: space-between; gap: 30px; margin-bottom: 28px; page-break-inside: avoid; }
	.party { flex: 1; font-size: 11.5px; line-height: 1.6; }
	.party-name { font-weight: bold; font-size: 13px; margin-bottom: 4px; }
	.party-kicker { font-size: 10px; text-transform: uppercase; letter-spacing: 0.08em; color: #777777; margin-bottom: 6px; }

	.section-heading { font-size: 14px; font-weight: bold; border-bottom: 1.5px solid #1a1a1a; padding-bottom: 6px; margin-bottom: 10px; page-break-after: avoid; }

	table.items { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
	table.items th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: #777777; padding: 0 0 6px 0; border-bottom: 1px solid #d8d2c8; }
	table.items th.num { text-align: right; }
	table.items td { padding: 8px 0; font-size: 12px; border-bottom: 1px solid #ece7df; vertical-align: top; }
	table.items td.num { text-align: right; white-space: nowrap; }
	table.items tr { page-break-inside: avoid; }

	table.totals { width: 100%; margin-top: 4px; page-break-inside: avoid; }
	table.totals td { padding: 4px 0; font-size: 12px; }
	table.totals td.label { text-align: right; padding-right: 18px; color: #555555; }
	table.totals td.value { text-align: right; width: 110px; }
	table.totals tr.total td { font-weight: bold; font-size: 14px; border-top: 1.5px solid #1a1a1a; padding-top: 8px; }

	.bottom-row { display: flex; justify-content: space-between; gap: 30px; margin-top: 36px; page-break-inside: avoid; }
	.bottom-col { flex: 1; font-size: 10.5px; color: #444444; line-height: 1.6; }
	.bottom-heading { font-weight: bold; color: #1a1a1a; margin-bottom: 6px; }
	.signature-line { margin-top: 26px; border-top: 1px solid #1a1a1a; width: 70%; }
</style>
</head>
<body>
<div class="sheet">

	<div class="top-row">
		<div>
			<div class="doc-title">Devis</div>
			<div class="doc-ref">#{{ proposal.name }}</div>
		</div>
		<div class="meta-box">
			<div class="meta-line"><span class="meta-label">Date du devis :</span> {{ submitted_display }}</div>
			{%- if deadline_display -%}
			<div class="meta-line">
				<span class="meta-label">Validité de l'offre :</span> {{ deadline_display }}
				{%- if extended_display %} (rappel possible jusqu'au {{ extended_display }}){% endif -%}
			</div>
			{%- endif -%}
		</div>
	</div>

	<div class="parties-row">
		<div class="party">
			<div class="party-kicker">De</div>
			<div class="party-name">{{ agency.agency_name or "Agence" }}</div>
			{%- if agency.phone -%}<div>{{ (agency.phone_country_code ~ " ") if agency.phone_country_code else "" }}{{ agency.phone }}</div>{%- endif -%}
			{%- if agency.email -%}<div>{{ agency.email }}</div>{%- endif -%}
			{%- if agency.website -%}<div>{{ agency.website }}</div>{%- endif -%}
			{%- if agency.address -%}<div>{{ agency.address }}</div>{%- endif -%}
			{%- if agency.vat_number -%}<div>TVA : {{ agency.vat_number }}</div>{%- endif -%}
		</div>
		<div class="party" style="text-align: right;">
			<div class="party-kicker">À l'attention de</div>
			<div class="party-name">{{ (client.company_name if client else None) or "Client" }}</div>
			{%- if client and client.legal_id -%}<div>{{ client.legal_id_label or "N° d'identification" }} : {{ client.legal_id }}</div>{%- endif -%}
			{%- if client and client.country -%}<div>{{ client.country }}</div>{%- endif -%}
			{%- if project.location -%}<div>Projet : {{ project.location }}</div>{%- endif -%}
		</div>
	</div>

	<div class="section-heading">Description</div>
	<table class="items">
		<thead>
			<tr>
				<th>Désignation</th>
				<th class="num">Qté</th>
				<th class="num">P.U.</th>
				<th class="num">Total</th>
			</tr>
		</thead>
		<tbody>
			{%- if items -%}
				{%- for item in items -%}
				<tr>
					<td>{{ item.designation or "Prestation" }}{% if item.details %} — {{ item.details }}{% endif %}</td>
					<td class="num">{{ item.quantity or 1 }}</td>
					<td class="num">{{ money(item.unit_price) }}</td>
					<td class="num">{{ money((item.quantity or 1) * (item.unit_price or 0)) }}</td>
				</tr>
				{%- endfor -%}
			{%- else -%}
				<tr>
					<td>{{ proposal.description or project.title or "Prestation" }}</td>
					<td class="num">1</td>
					<td class="num">{{ money(proposal.amount) }}</td>
					<td class="num">{{ money(proposal.amount) }}</td>
				</tr>
			{%- endif -%}
		</tbody>
	</table>

	<table class="totals">
		<tr><td class="label">Sous-total :</td><td class="value">{{ money(ns.subtotal) }}</td></tr>
		{%- if vat_rate -%}
		<tr><td class="label">TVA ({{ vat_rate }}%) :</td><td class="value">{{ money(vat_amount) }}</td></tr>
		{%- endif -%}
		<tr class="total"><td class="label">TOTAL :</td><td class="value">{{ money(total) }}</td></tr>
	</table>

	<div class="bottom-row">
		<div class="bottom-col">
			<div class="bottom-heading">Conditions</div>
			{%- if deadline_display -%}
			<div>Cette offre est valable jusqu'au {{ deadline_display }}{% if extended_display %}, avec rappel possible jusqu'au {{ extended_display }}{% endif %}.</div>
			{%- endif -%}
			<div>Le paiement s'effectue via la plateforme Sortlist Pro après acceptation du devis.</div>
		</div>
		<div class="bottom-col">
			<div class="bottom-heading">Acceptation</div>
			<div>Signature précédée de la mention « bon pour accord »</div>
			<div class="signature-line"></div>
		</div>
	</div>

</div>
</body>
</html>
